            if (billingInvoice.BillingPeriodEndDateOption.IsSet)
                writer.WriteString("billing_period_end_date", billingInvoice.BillingPeriodEndDateOption.Value!.Value.ToString(BillingPeriodEndDateFormat));

            if (billingInvoice.BillingPeriodStartDateOption.IsSet)
                writer.WriteString("billing_period_start_date", billingInvoice.BillingPeriodStartDateOption.Value!.Value.ToString(BillingPeriodStartDateFormat));

            if (billingInvoice.CurrencyOption.IsSet)
            {
                var currencyRawValue = CurrencyValueConverter.ToJsonValue(billingInvoice.Currency!.Value);
                writer.WriteString("currency", currencyRawValue);
            }
            if (billingInvoice.DocumentTypeOption.IsSet)
            {
                var documentTypeRawValue = BillingInvoiceDocumentTypeValueConverter.ToJsonValue(billingInvoice.DocumentType!.Value);
                writer.WriteString("document_type", documentTypeRawValue);
            }
            if (billingInvoice.IdOption.IsSet)
                writer.WriteString("id", billingInvoice.Id);

            if (billingInvoice.InvoiceDueDateOption.IsSet)
                writer.WriteString("invoice_due_date", billingInvoice.InvoiceDueDateOption.Value!.Value.ToString(InvoiceDueDateFormat));

            if (billingInvoice.PaymentTermsOption.IsSet)
                writer.WriteString("payment_terms", billingInvoice.PaymentTerms);

            if (billingInvoice.StatusOption.IsSet)
            {
                var statusRawValue = BillingInvoiceStatusValueConverter.ToJsonValue(billingInvoice.Status!.Value);
                writer.WriteString("status", statusRawValue);
            }
        }
    }
}
